// These URLs are generated by the isolated runner, never loaded from .dev.vars.
// Refuse external hosts before any test can open a database connection.
export function testDatabaseUrl(variable: 'WORKER_TEST_DATABASE_URL' | 'WORKER_TEST_ADMIN_URL'): string | undefined {
  const value = process.env[variable]
  if (!value) return undefined
  let url: URL
  try {
    url = new URL(value)
  } catch {
    throw new Error('隔离数据库地址无效')
  }
  const role = variable === 'WORKER_TEST_DATABASE_URL' ? 'lifespace_worker' : 'postgres'
  if (
    !['postgres:', 'postgresql:'].includes(url.protocol) ||
    url.hostname !== '127.0.0.1' ||
    !url.port ||
    url.username !== role ||
    url.pathname !== '/postgres' ||
    url.search ||
    url.hash
  )
    throw new Error('仅允许 runner 创建的本机隔离数据库')
  return value
}
